// ===== QUICK SEARCH ENGINE =====
var _srSel = -1;
function _srAr(n){return (''+n).replace(/[0-9]/g,function(d){return '٠١٢٣٤٥٦٧٨٩'[d];});}

function openSearch(){
  document.getElementById('search-overlay').classList.add('show');
  document.body.style.overflow='hidden';
  setTimeout(function(){document.getElementById('search-input').focus();},80);
  srQuery('');
}
function srClose(e){
  if(e&&e.target!==document.getElementById('search-overlay'))return;
  _srDismiss();
}
function _srDismiss(){
  document.getElementById('search-overlay').classList.remove('show');
  document.getElementById('search-input').value='';
  document.getElementById('search-clear').classList.remove('show');
  document.body.style.overflow='';
  _srSel=-1;
}
function srClear(){
  document.getElementById('search-input').value='';
  document.getElementById('search-clear').classList.remove('show');
  srQuery('');
  document.getElementById('search-input').focus();
}
function srKey(e){
  var items=document.querySelectorAll('.sr-item');
  if(e.key==='Escape'){_srDismiss();return;}
  if(e.key==='ArrowDown'){e.preventDefault();_srSel=Math.min(_srSel+1,items.length-1);_srHl(items);}
  else if(e.key==='ArrowUp'){e.preventDefault();_srSel=Math.max(_srSel-1,0);_srHl(items);}
  else if(e.key==='Enter'){
    if(_srSel>=0&&items[_srSel])items[_srSel].click();
    else if(items.length===1)items[0].click();
  }
}
function _srHl(items){
  items.forEach(function(el,i){el.classList.toggle('sr-active',i===_srSel);});
  if(items[_srSel])items[_srSel].scrollIntoView({block:'nearest'});
}
function _srMark(text,q){
  if(!q)return text;
  return text.replace(new RegExp('('+q.replace(/[\-\[\]{}()*+?.,\\^$|#\s]/g,'\\$&')+')','gi'),'<mark>$1</mark>');
}
function srQuery(q){
  q=q.trim();
  document.getElementById('search-clear').classList.toggle('show',q.length>0);
  _srSel=-1;
  var sem=window._activeSemester||2;
  // Only exclude items explicitly tagged for the other semester — items with no "sem" tag
  // (semester not yet determined, or available in both) are always included.
  var _srInSemester=function(s){ return !s.sem || s.sem===sem; };
  var results,hint='';
  if(!q){
    results=_SEARCH_INDEX.filter(_srInSemester).slice(0,8);
    hint='<div class="sr-hint">استقصاءات مقترحة</div>';
  } else {
    var ql=q.toLowerCase();
    results=_SEARCH_INDEX.filter(function(s){
      if(!_srInSemester(s)) return false;
      return s.name.indexOf(q)>-1||s.num.indexOf(q)>-1||s.desc.indexOf(q)>-1||
             s.gl.indexOf(q)>-1||s.key.toLowerCase().indexOf(ql)>-1;
    }).slice(0,12);
  }
  var html=hint;
  if(results.length===0){
    html='<div class="sr-empty">لا توجد نتائج لـ «'+q+'»</div>';
  } else {
    results.forEach(function(s,i){
      var name=q?_srMark(s.name,q):s.name;
      var meta=s.num||(s.desc.length>50?s.desc.slice(0,50)+'…':s.desc);
      html+='<div class="sr-item" data-key="'+s.key+'" data-grade="'+s.grade+'">';
      html+='<div class="sr-emoji">'+s.emoji+'</div>';
      html+='<div class="sr-body"><div class="sr-name">'+name+'</div>';
      html+='<div class="sr-meta">'+meta+'</div></div>';
      html+='<div class="sr-grade-badge">ص'+s.grade+'</div></div>';
    });
  }
  document.getElementById('search-results').innerHTML=html;
  document.getElementById('sr-count').textContent=_srAr(results.length);
}
// Event delegation for search results
document.addEventListener('click', function(e){
  var item = e.target.closest('.sr-item');
  if(item && document.getElementById('search-overlay').classList.contains('show')){
    srOpen(item.dataset.key, parseInt(item.dataset.grade));
  }
});

function srOpen(key,grade){
  _srDismiss();
  if(grade&&typeof switchGrade==='function')switchGrade(grade);
  setTimeout(function(){if(typeof openSim==='function')openSim(key);},150);
}
document.addEventListener('keydown',function(e){
  if((e.ctrlKey&&e.key==='k')||(e.key==='/'&&document.activeElement===document.body)){
    var app=document.getElementById('app');
    if(app&&app.classList.contains('open')){e.preventDefault();openSearch();}
  }
});
// ===== END QUICK SEARCH =====

